    H = 1350;
  const PAD_L = 68;
  const PAD_TOP = 135;
  const PAD_BOT = 135;
  const BG = '#0d1f3c';
  const TEXT = '#f8fafc';
  const LABEL = 'rgba(248,250,252,0.65)';
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = BG;
  ctx.fillRect(0, 0, W, H);
  function ls(size) {
    return `${(size * -0.025).toFixed(2)}px`;
  }
